// Isolated backend audit: generated bytes and an in-memory driver, never a Zenoh connection.
// Run: node --expose-gc --import tsx scripts/backend_benchmark.ts
import { performance } from 'node:perf_hooks';
import { setImmediate as yieldTurn, setTimeout as delay } from 'node:timers/promises';
import { createCartoBackend } from '../packages/core/src/backend/cartoBackend';
import { createRingBuffer } from '../packages/core/src/backend/ringBuffer';
import { createPayloadCache } from '../packages/core/src/backend/payloadCache';
import type { SubscribeOptions, ZenohDriver } from '../packages/core/src/zenoh/driver';

async function main() {
  if (!global.gc) throw new Error('Run Node with --expose-gc to measure memory after collection.');
  const gc = global.gc;
  const median = (values: number[]) => values.sort((a, b) => a - b)[Math.floor(values.length / 2)];
  const timings = [200, 20000].map((capacity) => {
    const measure = (circular: boolean) => {
      const values: number[] = [];
      for (let run = 0; run < 3; run++) {
        const ring = createRingBuffer<number>(capacity);
        const array: number[] = [];
        const start = performance.now();
        for (let index = 0; index < 200000; index++) {
          if (circular) ring.push(index);
          else {
            array.push(index);
            if (array.length > capacity) array.shift();
          }
        }
        values.push(performance.now() - start);
        const retained = circular ? ring.toArray() : array;
        if (retained.length !== capacity || retained.at(-1) !== 199999)
          throw new Error('Buffer benchmark lost retained values.');
      }
      return Number(median(values).toFixed(2));
    };
    return {
      capacity,
      messages: 200000,
      previousArrayMs: measure(false),
      circularBufferMs: measure(true)
    };
  });
  const attachments = new Map<string, SubscribeOptions>();
  const driver: ZenohDriver = {
    connect: async () => ({ driver: 'memory benchmark', features: ['subscribe'] }),
    disconnect: async () => {
      attachments.clear();
    },
    subscribe: async (options) => {
      attachments.set(options.subscriptionId, options);
    },
    unsubscribe: async (id) => {
      attachments.delete(id);
    },
    publish: async () => {},
    declareQueryable: async () => {},
    undeclareQueryable: async () => {}
  };
  const backend = createCartoBackend({ createDriver: () => driver });
  let received = 0;
  backend.setEventSink({
    sendStatus: () => {},
    sendMessage: (batch) => {
      received = batch.capture?.received ?? received;
    }
  });
  const payload = new Uint8Array(4096).fill(97);
  const snapshot = async () => {
    await yieldTurn();
    gc();
    await yieldTurn();
    gc();
    const memory = process.memoryUsage();
    return {
      heapMiB: Number((memory.heapUsed / 1048576).toFixed(2)),
      arrayBuffersMiB: Number((memory.arrayBuffers / 1048576).toFixed(2)),
      rssMiB: Number((memory.rss / 1048576).toFixed(2))
    };
  };
  const cycles = [];
  try {
    for (let cycle = 0; cycle < 12; cycle++) {
      await backend.connect({
        endpoint: 'ws://benchmark.invalid/',
        healthCheckIntervalMs: 0,
        reconnect: { enabled: false }
      });
      const id = await backend.subscribe('benchmark/**', 200);
      const start = performance.now();
      for (let index = 0; index < 10000; index++) {
        attachments.get(id)!.onMessage({ key: `benchmark/${index % 1200}`, payload });
        if (index % 250 === 0) await yieldTurn();
      }
      await delay(20);
      if (received !== 10000) throw new Error(`Unexpected received count: ${received}`);
      const active = await snapshot();
      const ingestMs = Math.round(performance.now() - start);
      await backend.disconnect();
      if (attachments.size) throw new Error('Driver subscriptions leaked.');
      cycles.push({ cycle: cycle + 1, ingestMs, active, disconnected: await snapshot() });
    }
  } finally {
    await backend.disconnect();
  }
  // Exercise the production shared budget with large samples from ten subscriptions.
  const cache = createPayloadCache();
  const largePayload = new Uint8Array(4 * 1024 * 1024).fill(42);
  const beforeRetention = await snapshot();
  for (let index = 0; index < 200; index++) {
    cache.set(`subscription-${index % 10}`, `message-${index}`, largePayload, 200);
    if (cache.stats().bytes > cache.stats().maxBytes)
      throw new Error('Shared payload budget exceeded.');
    if (index % 8 === 0) {
      await yieldTurn();
      gc();
    }
  }
  const retained = cache.stats();
  const duringRetention = await snapshot();
  cache.clear();
  const afterRetention = await snapshot();
  const sharedRetention = {
    subscriptions: 10,
    incomingPayloadBytes: 200 * largePayload.byteLength,
    payloadBytes: largePayload.byteLength,
    retained,
    afterClear: cache.stats(),
    beforeRetention,
    duringRetention,
    afterRetention
  };
  console.log(
    JSON.stringify(
      {
        node: process.version,
        sharedRetention,
        ringBuffer: timings,
        memory: {
          messagesPerCycle: 10000,
          payloadBytes: payload.byteLength,
          retainedLimit: 200,
          warmupCycles: 2,
          cycles
        }
      },
      null,
      2
    )
  );
}
void main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
